# The table is keyed by GENERATOR ROW; records are looked
# up by the slug each row's record carries, which for the
# surfaces the database already knew is its existing slug.
_BY_SLUG = {c.get('record_slug', k): c
            for k, c in FE_CELLS.items()}


def facts_for(slug):
    """`definition` fragment for a slug, or {}."""
    cell = _BY_SLUG.get(slug)
    if not cell:
        return {}
    return {'definition': {'evolver_cell': cell}}
